INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41011, 'Zechariah 14:6', 'Zechariah', 14, 6, 'په هغه ورځ به نۀ رڼا او نۀ يخ او نۀ کنګل وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_6.mp3', '', 1761754199, 1761754199),
(41012, 'Zechariah 14:7', 'Zechariah', 14, 7, 'دا به يو بې‌مثاله ورځ وى، نۀ به ورځ وى نۀ به شپه وى، مالِک خُدائ ته به د دې پته وى. د ماښام په وخت کښې به هم رڼا وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_7.mp3', '', 1761754199, 1761754199),
(41013, 'Zechariah 14:8', 'Zechariah', 14, 8, 'په هغه ورځ به د ژوند اوبۀ د يروشلم نه بهيږى، نيمې به د مشرق سمندر ته او نيمې به د مغرب سمندر ته، په ګرمۍ او يخنۍ کښې بهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_8.mp3', '', 1761754199, 1761754199),
(41014, 'Zechariah 14:9', 'Zechariah', 14, 9, 'مالِک خُدائ به په ټوله زمکه بادشاه وى، په هغه ورځ به صرف يو مالِک خُدائ وى، او صرف د هغۀ نوم به وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_9.mp3', '', 1761754199, 1761754199),
(41015, 'Zechariah 14:10', 'Zechariah', 14, 10, 'ټول مُلک، د جبع نه تر رِمون پورې، د يروشلم جنوب طرف ته، به لکه د عرابه د وادۍ په شان شى. خو يروشلم به بيا اوچت شى او په خپل ځائ به ودريږى، د بنيامين د دروازې نه تر د زړې دروازې پورې، د ګوټ دروازې پورې، او د حنن‌ايل د برج نه تر د شاهى انګورو د لنګرو پورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_10.mp3', '', 1761754199, 1761754199),
(41016, 'Zechariah 14:11', 'Zechariah', 14, 11, 'دا به بيا آباد شى، دا به بيا هيڅکله هم تباه نۀ شى. يروشلم به محفوظ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_11.mp3', '', 1761754199, 1761754199),
(41017, 'Zechariah 14:12', 'Zechariah', 14, 12, 'دا هغه وبا ده چې مالِک خُدائ به په دې هغه خلق مړۀ کړى چا چې د يروشلم خلاف جنګ کړے وو. د هغوئ غوښې به سخا شى چې لا دوئ په خپلو پښو ولاړ وى، د دوئ سترګې به په خپل ځائ سخا شى، او د دوئ ژبې به د دوئ په خُلو کښې سخا شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_12.mp3', '', 1761754199, 1761754199),
(41018, 'Zechariah 14:13', 'Zechariah', 14, 13, 'په هغه ورځ به مالِک خُدائ خلق په لوئ درد اخته کړى. هر سړے به د بل لاس راونيسى، او هغوئ به په يو بل حمله وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_13.mp3', '', 1761754199, 1761754199),
(41019, 'Zechariah 14:14', 'Zechariah', 14, 14, 'تر دې چې يهوداه او يروشلم به په خپلو کښې جنګ کوى. د ګېرچاپېره ټولو قومونو دولت به راغونډ کړے شى، چې په کښې به په لوئ مِقدار سرۀ زر او سپين زر او جامې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_14.mp3', '', 1761754199, 1761754199),
(41020, 'Zechariah 14:15', 'Zechariah', 14, 15, 'هم دغه شان به په آسونو او قچرو، اوښانو، خرونو او چې څومره ځناور په هغه ځائ کښې دى افت نازل شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_15.mp3', '', 1761754199, 1761754199),
(41021, 'Zechariah 14:16', 'Zechariah', 14, 16, 'بيا به د ټولو قومونو پاتې ژوندى کسان چا چې په يروشلم حمله کړې وه کال په کال د بادشاه، مالِک خُدائ ربُ الافواج عبادت ته هلته ځى، او د جونګړو اختر به کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_16.mp3', '', 1761754199, 1761754199),
(41022, 'Zechariah 14:17', 'Zechariah', 14, 17, 'خو کۀ هر قوم يروشلم ته د تلو او د بادشاه مالِک خُدائ ربُ الافواج د عبادت نه اِنکار وکړى، نو په هغوئ به باران نۀ کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_17.mp3', '', 1761754199, 1761754199),
(41023, 'Zechariah 14:18', 'Zechariah', 14, 18, 'کۀ مِصريان هلته لاړ نۀ شى او خپل ځانونه هلته حاضر نۀ کړى، نو په هغوئ به باران نۀ کيږى. مالِک خُدائ به په هغوئ هغه وبا نازله کړى چې مالِک خُدائ يې په هغه قومونو رالېږى څوک چې د جونګړو اختر لمانځلو له نۀ ځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_18.mp3', '', 1761754199, 1761754199),
(41024, 'Zechariah 14:19', 'Zechariah', 14, 19, 'دا به د مِصر او د هغه ټولو قومونو سزا وى چې څوک د جونګړو اختر لمانځلو له نۀ ځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_19.mp3', '', 1761754199, 1761754199),
(41025, 'Zechariah 14:20', 'Zechariah', 14, 20, 'په هغه ورځ به د آسونو په ګونګرو باندې هم ليکلى وى ”مالِک خُدائ ته مقدس کړے شوى“ او د پخلى دېګونه د مالِک خُدائ په کور کښې به لکه د هغه مقدسو لوښو په شان وى چې د قربان‌ګاه په وړاندې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_20.mp3', '', 1761754199, 1761754199),
(41026, 'Zechariah 14:21', 'Zechariah', 14, 21, 'هر يو لوښے به په يروشلم او يهوداه کښې مالِک خُدائ ربُ الافواج ته مقدس وى. او هغوئ ټول چې قربانۍ کولو له راغلى دى هغوئ به څۀ لوښى واخلى او په کښې به پخلى کولے شى. او په هغه ورځ به د مالِک خُدائ ربُ الافواج په کور کښې يو کنعانى سوداګر هم پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_21.mp3', '', 1761754199, 1761754199),
(41027, 'Ezekiel 14:1', 'Ezekiel', 14, 1, 'د اسراییلو ځینې مشران راغلل چې زما سره د خدای د رضا د معلومولو په هکله مشوره وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_1.mp3', '', 1761754199, 1761754199),
(41028, 'Ezekiel 14:2', 'Ezekiel', 14, 2, 'بیا څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_2.mp3', '', 1761754199, 1761754199),
(41029, 'Ezekiel 14:3', 'Ezekiel', 14, 3, '«ای فاني انسانه، دې خلکو بتانو ته په خپلو زړونو کې ځای ورکړی دی او بت پرستي د هغوی د ګناه سبب ګرځېدلې ده. ایا هغوی فکر کوي چې زه به ورته مشوره ورکړم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_3.mp3', '', 1761754199, 1761754199),
(41030, 'Ezekiel 14:4', 'Ezekiel', 14, 4, 'زما یعنې څښتن تعالی له خوا هغوی ته ووایه: ‹هر اسراییلی چې د بتانو څخه پیروي کوي او د ګناه په لاره ځي او په هغه وخت کې کله چې هغه د مشورې دپاره پیغمبر ته راځي، نو زه څښتن به خپله هغوی ته ځواب ورکوم، داسې ځواب چې دا بت پرستان د هغه لایق دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_4.mp3', '', 1761754199, 1761754199),
(41031, 'Ezekiel 14:5', 'Ezekiel', 14, 5, 'زه به هغوی ته ځواب ورکړم ترڅو وکولای شم د اسراییلو خلک چې د خپلو ټولو بتانو له امله زما څخه لېرې شوي دي، بېرته خپل ځان ته راوګرځوم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_5.mp3', '', 1761754199, 1761754199),
(41032, 'Ezekiel 14:6', 'Ezekiel', 14, 6, 'نو اسراییلیانو ته ووایه چې زه څښتن تعالی داسې وایم: ‹توبه وباسئ او خپل بتان او د کرکې وړ کارونه پرېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_6.mp3', '', 1761754199, 1761754199),
(41033, 'Ezekiel 14:7', 'Ezekiel', 14, 7, 'فرض کړئ یو اسراییلی یا کوم پردی سړی چې په اسراییلو کې اوسیږي او خپل ځان زما نه بېلوي، هغه په خپل زړه کې بتانو ته ځای ورکوي او هغه دا بتان د خپلو سترګو په وړاندې ږدي او هغه د ګناه خواته ځي. کله چې هغه د مشورې دپاره پیغمبر ته راځي، نو زه څښتن به په خپله هغه ته ځواب ورکړم!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_7.mp3', '', 1761754199, 1761754199),
(41034, 'Ezekiel 14:8', 'Ezekiel', 14, 8, 'زه به د هغه په ضد شم. هغه به د نورو دپاره د عبرت سبب وګرځوم. زه به یې د خپل قوم نه وباسم، بیا به تاسو په دې پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_8.mp3', '', 1761754199, 1761754199),
(41035, 'Ezekiel 14:9', 'Ezekiel', 14, 9, 'که چېرې یو پیغمبر وغولیږي او غلط ځواب ورکړي، نو دلیل به یې دا وي چې هغه ما یعنې څښتن غولولی دی. زه به هغه پیغمبر ته سزا ورکړم او د خپل قوم اسراییلو نه به یې بیخي لېرې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_9.mp3', '', 1761754199, 1761754199),
(41036, 'Ezekiel 14:10', 'Ezekiel', 14, 10, 'هغه پیغمبر او هغه څوک چې د هغه نه مشوره اخلي، دواړو ته به یوشان سزا ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_10.mp3', '', 1761754199, 1761754199),
(41037, 'Ezekiel 14:11', 'Ezekiel', 14, 11, 'دا کار د دې دپاره کوم چې نور اسراییلیان زما څخه بې‌لارې نه شي او خپل ځانونه نور په ګناهونو باندې ناپاکه نه کړي. نو هغوی به زما قوم وي او زه به د هغوی خدای یم. څښتن تعالی داسې وویل.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_11.mp3', '', 1761754199, 1761754199),
(41038, 'Ezekiel 14:12', 'Ezekiel', 14, 12, 'څښتن زما سره خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_12.mp3', '', 1761754199, 1761754199),
(41039, 'Ezekiel 14:13', 'Ezekiel', 14, 13, 'هغه وویل: «ای فاني انسانه، کله چې د یو هېواد خلک ګناه او زما سره بې‌وفایي وکړي، نو زه به د هغوی په وړاندې لاس پورته کړم او خواړه به ورباندې بند کړم. زه به ورباندې قحطي راولم او خلک او حیوانات به یې ووژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_13.mp3', '', 1761754199, 1761754199),
(41040, 'Ezekiel 14:14', 'Ezekiel', 14, 14, 'که هغه درې کسان یعنې نوح، دانیال او ایوب هم هلته اوسي، نو زه به هغوی د خپلې رښتینولۍ له امله وژغورم، خو یوازې هغوی به زه ژغورم. څښتن تعالی داسې وویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_14.mp3', '', 1761754199, 1761754199),
(41041, 'Ezekiel 14:15', 'Ezekiel', 14, 15, 'یا فرض کړئ زه هغه هېواد ته ځنګلي حیوانات ورولېږم چې خلک وخوري او هغه هېواد دومره خطرناکه کړي چې هېڅوک په هغه لاره تېرېدلی نه شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_15.mp3', '', 1761754199, 1761754199),
(41042, 'Ezekiel 14:16', 'Ezekiel', 14, 16, 'حتی که هغه درې کسان هم هلته اوسي، نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې هغوی به هم ونه شي کولای چې خپل زامن او لورګانې وژغوري. یوازې هغوی به وژغورل شي او هغه هېواد به وران او ویجاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_16.mp3', '', 1761754199, 1761754199),
(41043, 'Ezekiel 14:17', 'Ezekiel', 14, 17, 'یا فرض کړئ زه په هغه وطن باندې جنګ راولم او د دښمن لښکرې ورولېږم چې انسانان او حیوانات ټول له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_17.mp3', '', 1761754199, 1761754199),
(41044, 'Ezekiel 14:18', 'Ezekiel', 14, 18, 'که هغه درې کسان هم هلته اوسي، نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې هغوی به ونه شي کولای چې خپل زامن او لورګانې وژغوري. یوازې هغوی به وژغورل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_18.mp3', '', 1761754199, 1761754199),
(41045, 'Ezekiel 14:19', 'Ezekiel', 14, 19, 'یا فرض کړئ زه په هغه هېواد باندې وبا راولم او د قهر له لاسه د ډېرو انسانانو او حیواناتو ژوند واخلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_19.mp3', '', 1761754199, 1761754199),
(41046, 'Ezekiel 14:20', 'Ezekiel', 14, 20, 'که نوح، دانیال او ایوب هم هلته اوسي، نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې هغوی به نه شي کولای چې خپل زوی او لور وژغوري. د هغوی رښتینولي به یوازې د هغوی ژوند وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_20.mp3', '', 1761754199, 1761754199),
(41047, 'Ezekiel 14:21', 'Ezekiel', 14, 21, 'څښتن تعالی داسې وایي: ‹دا به څومره بده وي چې زه په اورشلیم باندې څلور ډېرې سختې سزاګانې یعنې جنګ، قحطي، ځنګلي حیوانات او وبا ورولېږم چې انسانان او حیوانات ټول ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_21.mp3', '', 1761754199, 1761754199),
(41048, 'Ezekiel 14:22', 'Ezekiel', 14, 22, 'ګورئ، ځینې سړي او ښځې به په اورشلیم کې ژوندي پاتې شي او هغوی به د هغه ځای څخه دباندې وویستل شي. کله چې هغوی په بابل کې ستاسو خواته راشي، نو وبه وینئ چې هغوی څومره بدعمله خلک دي او په دې به قانع شئ، ځکه کومه سزا چې ما اورشلیم ته ورکړې ده، هغه عادلانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_22.mp3', '', 1761754199, 1761754199),
(41049, 'Ezekiel 14:23', 'Ezekiel', 14, 23, 'هو، تاسو به په دې قانع شئ، څه چې ما څښتن تعالی کړي دي، زه په حقه یم. څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel14_verse_23.mp3', '', 1761754199, 1761754199),
(41050, 'Isaiah 18:1', 'Isaiah', 18, 1, 'افسوس د ایتوپیا په حال چې په سیندونو کې یې د کشتۍ ګانو د بادبان اواز اورېدل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah18_verse_1.mp3', '', 1761754199, 1761754199),
(41051, 'Isaiah 18:2', 'Isaiah', 18, 2, 'هغه وطن خپل استازي د بحیرې له لارې په داسې کشتۍ ګانو کې لېږي چې د لوخو څخه جوړې شوې دي. ای چالاکو استازو، دا پیغام هغه قوم ته یوسئ چې قوي او جنګیالی دی، هغه چې لوړ قدونه او ښویه پوستکي لري او د ټولې نړۍ خلک ورڅخه وېریږي، د هغه وطن څخه چې په سیندونو باندې وېشل شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah18_verse_2.mp3', '', 1761754199, 1761754199),
(41052, 'Isaiah 18:3', 'Isaiah', 18, 3, 'ای د ټولې نړۍ خلکو واورئ! کله چې بیرغ د نښې په توګه د غرونو په سرونو درول کیږي، وګورئ! د سورني هغه اواز ته چې د جګړې دپاره غږول کیږي، غوږ ونیسئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah18_verse_3.mp3', '', 1761754199, 1761754199),
(41053, 'Isaiah 18:4', 'Isaiah', 18, 4, 'ځکه چې څښتن ماته داسې وویل: «زه به د خپل استوګنځي څخه داسې په ارامۍ سره لاندې ګورم لکه څنګه چې پرخه د لو په وخت کې وریږي او لکه لمر چې د ورځې په ګرمۍ کې ځلیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah18_verse_4.mp3', '', 1761754199, 1761754199),
(41054, 'Isaiah 18:5', 'Isaiah', 18, 5, 'مخکې له دې چې انګور راټول شي، کله چې د ګل پاڼې راوغورځیږي او انګور پاخه شي، څښتن به د انګورو له تاکونو څخه نودې په چاقو او څانګې به یې په اره باندې پرې کړي او لېرې وغورځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah18_verse_5.mp3', '', 1761754199, 1761754199),
(41055, 'Isaiah 18:6', 'Isaiah', 18, 6, 'هغه به ټول د غرونو ښکاري مرغانو او وحشي حیواناتو ته پراته وي. په اوړي کې به هغه د مرغانو خوراک وي او په ژمي کې به د حیواناتو خوراک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah18_verse_6.mp3', '', 1761754199, 1761754199),
(41056, 'Isaiah 18:7', 'Isaiah', 18, 7, 'په هغه وخت کې به هغه قوي او جنګیالی قوم چې لوړ قدونه او ښویه پوستکي لري او د ټولې نړۍ خلک ورڅخه وېریږي، د هغه وطن څخه چې په سیندونو باندې وېشل شوی دی، د صهیون غره ته راشي، هغه ځای ته چې د مطلق قادر څښتن نوم په کې یادیږي او هغه ته به نذرانې او سوغاتونه راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah18_verse_7.mp3', '', 1761754199, 1761754199),
(41057, 'Ezekiel 2:1', 'Ezekiel', 2, 1, 'هغه ماته وویل: «ای فاني انسانه، پاڅېږه او په خپلو پښو ودرېږه. زه غواړم ستا سره خبرې وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_1.mp3', '', 1761754199, 1761754199),
(41058, 'Ezekiel 2:2', 'Ezekiel', 2, 2, 'کله چې هغه زما سره خبرې کولې، نو د خدای روح په ما باندې نازل شو او زه یې په پښو ودرولم او ما د هغه خبرې واورېدلې چې داسې یې ماته ویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_2.mp3', '', 1761754199, 1761754199),
(41059, 'Ezekiel 2:3', 'Ezekiel', 2, 3, '«ای فاني انسانه، زه تا د اسراییلو قوم ته لېږم، یعنې هغه سرکښه قوم ته چې زما په وړاندې یې سرکښي کړې ده. هغوی او د هغوی نیکونه تر نن ورځې پورې زما په وړاندې سرکښي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_3.mp3', '', 1761754199, 1761754199),
(41060, 'Ezekiel 2:4', 'Ezekiel', 2, 4, 'اوسني خلک هم سرزوري دي او زما درناوی نه کوي، نو زه څښتن تعالی تا هغوی ته لېږم چې زما پیغام هغوی ته ورسوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_4.mp3', '', 1761754199, 1761754199),
(41061, 'Ezekiel 2:5', 'Ezekiel', 2, 5, 'که دا خلک غوږ نیسي یا نه نیسي، دا سرکښه قوم به پوه شي چې د هغوی په منځ کې یو پیغمبر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_5.mp3', '', 1761754199, 1761754199),
(41062, 'Ezekiel 2:6', 'Ezekiel', 2, 6, 'خو ای فاني انسانه، د هغه قوم او د هغو د خبرو څخه مه وېرېږه، که د هغوی خبرې لکه د اغزن بوټي او د لړم د نېش په شان هم وي بیاهم مه وېرېږه، ځکه چې هغوی یو سرکښه قوم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_6.mp3', '', 1761754199, 1761754199),
(41063, 'Ezekiel 2:7', 'Ezekiel', 2, 7, 'هرڅه چې زه درته وایم هغوی ته یې ووایه، که هغوی ورته غوږ ونیسي او یا یې ونه نیسي. ځکه چې هغوی یو سرکښه قوم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_7.mp3', '', 1761754199, 1761754199),
(41064, 'Ezekiel 2:8', 'Ezekiel', 2, 8, 'خو ای فاني انسانه، څه چې زه درته وایم، نو غوږ ورته ونیسه. د هغه سرکښه قوم په شان نه شې. خوله دې خلاصه کړه او څه چې تاته درکوم، هغه وخوره.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_8.mp3', '', 1761754199, 1761754199),
(41065, 'Ezekiel 2:9', 'Ezekiel', 2, 9, 'په همدې شېبه مې ولیدل چې یو لاس زما خواته را‌اوږد شو او په هغه کې یو طومار ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_9.mp3', '', 1761754199, 1761754199),
(41066, 'Ezekiel 2:10', 'Ezekiel', 2, 10, 'هغه طومار زما په مخکې پرانیست او د هغه په دواړو مخونو کې د ویر او افسوس کیسې لیکل شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel2_verse_10.mp3', '', 1761754199, 1761754199),
(41067, 'Exodus 13:1', 'Exodus', 13, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_1.mp3', '', 1761754199, 1761754199),
(41068, 'Exodus 13:2', 'Exodus', 13, 2, '«د اسراییلیانو ټول لومړني زېږېدل شوي زامن او هر لومړنی زېږېدلی نر حیوان ماته وقف کړه. هغه زما دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_2.mp3', '', 1761754199, 1761754199),
(41069, 'Exodus 13:3', 'Exodus', 13, 3, 'موسی قوم ته وویل: «دا ورځ په یاد ساتئ، یعنې هغه ورځ چې تاسو له مصر څخه چې په کې غلامان وئ، ووتلئ. دا هغه ورځ ده چې څښتن په خپل لوی قدرت سره تاسو له مصر څخه راوویستلئ. تاسو خمیره ډوډۍ مه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_3.mp3', '', 1761754199, 1761754199),
(41070, 'Exodus 13:4', 'Exodus', 13, 4, 'نن تاسو په لومړۍ میاشت چې د ابیب میاشت ده د مصر څخه روان یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_4.mp3', '', 1761754199, 1761754199),
(41071, 'Exodus 13:5', 'Exodus', 13, 5, 'کله چې څښتن تاسو د کنعانیانو، حیتیانو، اموریانو، حویانو او یبوسیانو غني او حاصلخېزې ځمکې ته چې د هغې وعده یې ستاسو د نیکونو سره کړې ده راولي، تاسو باید دا اختر د هر کال په لومړۍ میاشت ولمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_5.mp3', '', 1761754199, 1761754199),
(41072, 'Exodus 13:6', 'Exodus', 13, 6, 'اووه ورځې فطیره ډوډۍ وخورئ او په اوومه ورځ د څښتن د درناوي دپاره جشن ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_6.mp3', '', 1761754199, 1761754199),
(41073, 'Exodus 13:7', 'Exodus', 13, 7, 'اووه ورځې باید فطیره ډوډۍ وخورئ، ستاسو د هېواد په هېڅ ځای کې دې خمیره نه وي او نه دې خمیره ډوډۍ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_7.mp3', '', 1761754199, 1761754199),
(41074, 'Exodus 13:8', 'Exodus', 13, 8, 'د اختر په پیل کې خپلو زامنو ته داسې ووایئ چې مونږ دا هرڅه د هغه څه له امله کوو چې څښتن زمونږ دپاره د مصر څخه د راوتلو په وخت کې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_8.mp3', '', 1761754199, 1761754199),
(41075, 'Exodus 13:9', 'Exodus', 13, 9, 'دا مراسم به لکه د یوې نښې په شان چې تاسو یې په خپل لاس یا تندي باندې تړئ، یو یادګار وي. دا به تاسو ته په لوړ اواز د څښتن د شریعت دوامداره ویل در په یادوي، ځکه چې څښتن په خپل لوی قدرت تاسو د مصر څخه راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_9.mp3', '', 1761754199, 1761754199),
(41076, 'Exodus 13:10', 'Exodus', 13, 10, 'تاسو باید دا اختر د هر کال په ټاکل شوي وخت کې ولمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_10.mp3', '', 1761754199, 1761754199),
(41077, 'Exodus 13:11', 'Exodus', 13, 11, 'څښتن به تاسو د هغې وعدې سره سم چې تاسو او ستاسو د نیکونو سره یې کړې ده، د کنعانیانو وطن ته راولي. کله چې هغه وطن تاسو ته درکړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_11.mp3', '', 1761754199, 1761754199),
(41078, 'Exodus 13:12', 'Exodus', 13, 12, 'باید ټول لومړني زېږېدل شوي نارینه څښتن ته وقف کړئ. هر لومړنی زېږېدلی نر حیوان د څښتن دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_12.mp3', '', 1761754199, 1761754199),
(41079, 'Exodus 13:13', 'Exodus', 13, 13, 'تاسو باید هر نر خر بېرته په بیه واخلئ او د هغه په ځای یو وری قرباني کړئ. که چېرې تاسو نه غواړئ چې هغه خر بېرته په بیه واخلئ، نو د هغه ورمېږ مات کړئ. تاسو باید خپل ټول مشران زامن بېرته په بیه واخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_13.mp3', '', 1761754199, 1761754199),
(41080, 'Exodus 13:14', 'Exodus', 13, 14, 'کله چې په راتلونکې کې ستاسو څخه خپل زامن پوښتنه وکړي چې دا مراسم څه معنی لري؟ تاسو به هغوی ته په ځواب کې ووایئ چې څښتن په خپل لوی قدرت سره له مصر څخه چې مونږ په کې غلامان وو، راوویستلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_14.mp3', '', 1761754199, 1761754199),
(41081, 'Exodus 13:15', 'Exodus', 13, 15, 'هغه وخت چې د فرعون زړه سخت ؤ او مونږ یې نه پرېښودلو چې د مصر څخه لاړ شو، نو څښتن په مصر کې هر لومړنی زېږېدلی نر حیوان او انسان وواژه. ځکه مونږ څښتن ته هر لومړنی زېږېدلی نر حیوان قرباني کوو او خپل ټول لومړني زامن بېرته په بیه اخلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_15.mp3', '', 1761754199, 1761754199),
(41082, 'Exodus 13:16', 'Exodus', 13, 16, 'دا مراسم به لکه د یوې نښې په شان چې مونږ یې په خپلو لاسونو یا خپلو تندیو باندې وتړو، یو یادګار وي. دا به مونږ ته دا خبره را په یادوي چې څښتن په خپل قدرت مونږ له مصر څخه راوویستلو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_16.mp3', '', 1761754199, 1761754199),
(41083, 'Exodus 13:17', 'Exodus', 13, 17, 'کله چې فرعون د اسراییلو قوم پرېښود چې لاړ شي، که څه هم هغه لاره لنډه وه، خو خدای هغوی پرېنښودل چې د فلسطین په لارې باندې لاړ شي، ځکه چې خدای وویل: «که چېرې هغوی د جګړې سره مخامخ شي، کېدای شي چې خپله پرېکړه بدله کړي او بېرته مصر ته راستانه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_17.mp3', '', 1761754199, 1761754199),
(41084, 'Exodus 13:18', 'Exodus', 13, 18, 'د هغې په ځای یې هغوی د دښتې په لاره چې کږه وږه لار وه، د سرې بحیرې خواته بوتلل. اسراییلیان د جګړې دپاره په وسلو سمبال وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_18.mp3', '', 1761754199, 1761754199),
(41085, 'Exodus 13:19', 'Exodus', 13, 19, 'موسی د یوسف هډوکي د ځان سره یووړل، ځکه چې یوسف اسراییلیانو ته قسم ورکړی ؤ. هغه ویلي وو: «خدای به په رښتیا سره ستاسو مرستې ته راشي، بیا تاسو زما هډوکي د دې ځای څخه یوسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_19.mp3', '', 1761754199, 1761754199),
(41086, 'Exodus 13:20', 'Exodus', 13, 20, 'اسراییلیان د سوکوت څخه لاړل او په ایتام کې یې د دښتې په یوه ګوښه کې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_20.mp3', '', 1761754199, 1761754199),
(41087, 'Exodus 13:21', 'Exodus', 13, 21, 'د ورځې له خوا به څښتن په داسې ورېځ کې چې د ستنې په شان وه، د هغوی په مخکې روان ؤ چې هغوی ته لاره وروښایي او د شپې له خوا به په داسې اور کې چې د ستنې په شان ؤ روان ؤ، ترڅو هغوی ته رڼا وکړي. نو هغوی کولای شول چې شپه او ورځ سفر وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_21.mp3', '', 1761754199, 1761754199),
(41088, 'Exodus 13:22', 'Exodus', 13, 22, 'هغه ورېځ به په ورځ کې او هغه اور به په شپه کې د هغوی د مخې څخه نه لېرې کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus13_verse_22.mp3', '', 1761754199, 1761754199),
(41089, 'Judges 5:1', 'Judges', 5, 1, 'په هغه ورځ دبورې او د ابینوعم زوی باراق دا سندره وویله:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_1.mp3', '', 1761754199, 1761754199),
(41090, 'Judges 5:2', 'Judges', 5, 2, 'وکړئ ستاینه د څښتن چې مشري د اسراییلو رهبران کړي او په خوښۍ سره کړي خلک پیروي د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_2.mp3', '', 1761754199, 1761754199),
(41091, 'Judges 5:3', 'Judges', 5, 3, 'تاسې واورئ پاچاهانو وکړئ پام ای حاکمانو غږومه به زه ساز او وایم به سندره د اسراییلو څښتن خدای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_3.mp3', '', 1761754199, 1761754199),
(41092, 'Judges 5:4', 'Judges', 5, 4, 'کله لاړې د سعیر نه چې څښتنه چې راووتې له سیمې د ادومه ځمکه شوله په لړزه باران راغی د اسمان نه هو، شولې د ورېځو نه راتوی اوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_4.mp3', '', 1761754199, 1761754199),
(41093, 'Judges 5:5', 'Judges', 5, 5, 'د سینا د څښتن مخکې په لړزه شول غرونه د څښتن د اسراییلو خدای په مخکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_5.mp3', '', 1761754199, 1761754199),
(41094, 'Judges 5:6', 'Judges', 5, 6, 'د عنات د زوی شمجر په زمانه کې د یاعیل په زمانه کې کاروانو ته خطرناک وو سرکونه مسافر په کږو لارو باندې تلل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_6.mp3', '', 1761754199, 1761754199),
(41095, 'Judges 5:7', 'Judges', 5, 7, 'ای دبورې، د اسراییلو کلي وران پاتې شول ستا تر راتګه پورې تش پاتې شول ته راغلې اسراییلو ته د یوې مور په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_7.mp3', '', 1761754199, 1761754199),
(41096, 'Judges 5:8', 'Judges', 5, 8, 'کله چې غوره کړل اسراييلیانو نوي خدایان بیا په دې خاوره باندې جنګ راغی د څلوېښت زرو اسراییلو منځ کې یوه نېزه او یا یو سپر هم نه ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_8.mp3', '', 1761754199, 1761754199),
(41097, 'Judges 5:9', 'Judges', 5, 9, 'د اسراییل د قوماندانانو طرفدار یمه زه د هغو خلکو په خوا چې حاضر شوي دي په خپله خوښه وکړئ ستاینه د څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_9.mp3', '', 1761754199, 1761754199),
(41098, 'Judges 5:10', 'Judges', 5, 10, 'واورئ ای خلکو چې سپرېږئ په ښو خرو باندې او کښېنئ په کتو باندې او هغو خلکو چې پیاده ګرځئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_10.mp3', '', 1761754199, 1761754199),
(41099, 'Judges 5:11', 'Judges', 5, 11, 'د سندرغاړو اوازونه ګودرو کې واورئ بیانوي چې د څښتن فتحې د اسراییلو د قوم فتحې بیا د څښتن قوم روان شو ښکته د ښار د دروازو په طرف', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_11.mp3', '', 1761754199, 1761754199),
(41100, 'Judges 5:12', 'Judges', 5, 12, 'شه راویښه، شه راویښه، دبورې شه راویښه په سندره کړه لاس پورې ای باراقه، ای ته زوی د ابینوعمه پاڅه بوځه اسیران درسره خپل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_12.mp3', '', 1761754199, 1761754199),
