(41102, 'Judges 5:14', 'Judges', 5, 14, 'لاندې درې ته راغلل له افرایمه هغوی د بنیامین او د هغوی د خلکو پسې قوماندانان شولو راښکته د ماخیره څخه منصبداران له زبولونه راغلل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_14.mp3', '', 1761754199, 1761754199),
(41103, 'Judges 5:15', 'Judges', 5, 15, 'د دبورې سره مشران د یساکار راغلل هو، یساکار او هم باراق راغی دوی شول په منډه په دره کې د باراق پسې خو د روبین په قبیله کې شو پیدا نفاق پرېکړه ونه شوه کړای هغوی چې راشي که نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_15.mp3', '', 1761754199, 1761754199),
(41104, 'Judges 5:16', 'Judges', 5, 16, 'خپلو پسونو سره ولې تاسو پاتې شولئ؟ چې غوږ ونیسئ شپنو ته چې رمو ته اوازونه کاندي؟ هو، د روبین په قبیله کې شو پیدا نفاق پرېکړه یې ونه شوه کړای هغوی چې راشي که نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_16.mp3', '', 1761754199, 1761754199),
(41105, 'Judges 5:17', 'Judges', 5, 17, 'قبیله د جاد شوه پاتې د اردن د سیند ختیځ کې او قبیله د دان شوه پاتې کشتۍ ګانو سره قبیله د اشیر پاتې شوه د بحیرې په غاړه بندرونو ته نژدې شول ساکن هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_17.mp3', '', 1761754199, 1761754199),
(41106, 'Judges 5:18', 'Judges', 5, 18, 'خو د زبولون او نفتالي خلکو خطر کې واچاوه خپل ژوند د جنګ میدان کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_18.mp3', '', 1761754199, 1761754199),
(41107, 'Judges 5:19', 'Judges', 5, 19, 'پاچاهان راغلل، په تعنک کې د مجدو د ویالې څنګ کې هغوی وکړه جګړه د کنعان شاهانو وکړه جګړه خو یونوړل هغوی سپین زر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_19.mp3', '', 1761754199, 1761754199),
(41108, 'Judges 5:20', 'Judges', 5, 20, 'ستورو کوله چې جګړه د اسمانونو څخه چې په اسمان کې ګرځېدل به هغوی یو خوا بل خوا هغوی کوله جګړه په ضد د سیسرا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_20.mp3', '', 1761754199, 1761754199),
